Suggestion: resolve both via `realpathSync` before comparing. Pattern is already in the repo at `src/core/skills/manager.ts:159,169` and `src/core/utils/path-display.ts:40`.

```ts
import { realpathSync } from "node:fs";

const canonical = (p: string) => {
  try { return realpathSync(p); } catch { return p; }
};
const globalRoot = opts?.homeDir ?? homedir();
if (canonical(globalRoot) !== canonical(cwd)) {
  roots.push({ scope: "global", dir: globalRoot });
}
```

